SELECT "tradeid", "currenttradeid", "sk_customerid", "sk_accountid", "sk_securityid", "sk_companyid", "sk_dateid", "sk_timeid", "currentprice", "currentholding", "batchid" FROM (SELECT TRY_CAST((CAST(hh.HH_H_T_ID AS INT)) AS INT) AS "tradeid", TRY_CAST((CAST(hh.HH_T_ID AS INT)) AS INT) AS "currenttradeid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_customerid", TRY_CAST((CAST(t.T_CA_ID AS INT)) AS INT) AS "sk_accountid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_securityid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_companyid", TRY_CAST((CAST(STRFTIME(t.T_DTS, '%Y%m%d') AS INT)) AS INT) AS "sk_dateid", TRY_CAST((CAST(STRFTIME(t.T_DTS, '%Y%m%d') AS INT)) AS INT) AS "sk_timeid", TRY_CAST((CAST(t.T_TRADE_PRICE AS INT)) AS INT) AS "currentprice", TRY_CAST((hh.HH_AFTER_QTY) AS DECIMAL(6)) AS "currentholding", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS DECIMAL(5)) AS "batchid" FROM "Source"."HoldingHistory" AS hh LEFT JOIN "Source"."Trade" AS t ON hh.HH_T_ID = t.T_ID);
